pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IIncome {
    function blacklistAddress(address account, bool value) external;
    function _isBlacklisted(address) external view returns (bool);
    function owner() external view returns (address);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x3a91A88Ef4bB813BB99EF5a745bcb56e3A3b403b;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get the current owner
        address currentOwner = IIncome(TARGET).owner();

        // Step 2: Impersonate the owner
        vm.startPrank(currentOwner);

        // Step 3: Call blacklistAddress on ourselves
        IIncome(TARGET).blacklistAddress(address(this), true);

        vm.stopPrank();

        // Step 4: Verify we're blacklisted
        bool isBlacklisted = IIncome(TARGET)._isBlacklisted(address(this));
        require(isBlacklisted, "Failed to blacklist address");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
